{
  "claims": [
    {
      "claim": "The bill would change a grade-level condition in Tennessee’s financial aid law.",
      "summary_quote": "change a grade-level condition in Tennessee’s financial aid law",
      "verdict": "supported",
      "source_quote": "SECTION 1. Tennessee Code Annotated, Section 49-4-930(c)(2)(A), is amended by\n\ndeleting the subdivision and substituting:\n\n (A) Is a sophomore, junior, or senior in high school; or",
      "error_type": "none",
      "rationale": "The bill identifies its subject as financial aid and substitutes a high school grade-level condition."
    },
    {
      "claim": "The revised condition would include high school sophomores, juniors, and seniors.",
      "summary_quote": "include high school sophomores, juniors, and seniors",
      "verdict": "supported",
      "source_quote": "(A) Is a sophomore, junior, or senior in high school; or",
      "error_type": "none",
      "rationale": "The replacement condition expressly lists all three grade levels."
    },
    {
      "claim": "The bill would replace the text of Tennessee Code Annotated, Section 49-4-930(c)(2)(A).",
      "summary_quote": "replace the text of Tennessee Code Annotated, Section 49-4-930(c)(2)(A)",
      "verdict": "supported",
      "source_quote": "Tennessee Code Annotated, Section 49-4-930(c)(2)(A), is amended by\n\ndeleting the subdivision and substituting:",
      "error_type": "none",
      "rationale": "Section 1 expressly deletes and replaces the identified subdivision."
    },
    {
      "claim": "The bill would take effect July 1, 2025.",
      "summary_quote": "take effect July 1, 2025",
      "verdict": "supported",
      "source_quote": "This act takes effect July 1, 2025, the public welfare requiring it.",
      "error_type": "none",
      "rationale": "Section 2 specifies this effective date."
    }
  ]
}
